    + '*   http://www.apache.org/licenses/LICENSE-2.0\n'
    + '*\n'
    + '* Unless required by applicable law or agreed to in writing,\n'
    + '* software distributed under the License is distributed on an\n'
    + '* "AS IS" BASIS, WITHOUT WARRANTIES OR CONDITIONS OF ANY\n'
    + '* KIND, either express or implied.  See the License for the\n'
    + '* specific language governing permissions and limitations\n'
    + '* under the License.\n'
    + '*/\n';

function wrap(deps, args, code, tail) {
    return preamble
        + '\n\n/**\n'
        + ' * AUTO-GENERATED FILE. DO NOT MODIFY.\n'
        + ' */\n'
        + '(function(root, factory) {\n'
        + '    if (typeof define === \'function\' && define.amd) {\n'
        + '        // AMD. Register as an anonymous module.\n'
        + '        define([' + deps.amd + '], factory);\n'
        + '    } else if (\n'
        + '        typeof exports === \'object\' &&\n'
        + '        typeof exports.nodeName !== \'string\'\n'
        + '    ) {\n'
        + '        // CommonJS\n'
        + '        factory(' + deps.cjs + ');\n'
        + '    } else {\n'
        + '        // Browser globals\n'
        + '        factory(' + deps.global + ');\n'
        + '    }\n'
        + '})(this, function(' + args + ') {\n'
        + code
        + tail
        + '        \n'
        + '});';
}

/**
 * Strip the license header of the source file and turn the default export
 * into a plain `localeObj` variable.
 */
function transformSource(source) {
    return source.slice(source.indexOf('*/') + 2)
        .replace('export default', 'var localeObj =');
}

function buildLocale(fileName) {
    const localeName = path.basename(fileName, '.ts').replace(/^lang/, '');
    const code = transformSource(fs.readFileSync(path.join(SRC_DIR, fileName), 'utf8'));

    const echartsFile = wrap({
        amd: '\'exports\', \'echarts\'',
        cjs: 'exports, require(\'echarts/lib/echarts\')',
        global: '{}, root.echarts'
    }, 'exports, echarts', code, '\n    echarts.registerLocale(\'' + localeName + '\', localeObj);\n');

    const objFile = wrap({
        amd: '\'exports\'',
        cjs: 'exports',
        global: '{}'
    }, 'exports', code, '\n'
        + '    for (var key in localeObj) {\n'
        + '        if (localeObj.hasOwnProperty(key)) {\n'
        + '            exports[key] = localeObj[key];\n'
        + '        }\n'
        + '    }\n'
    );

    fs.writeFileSync(path.join(OUT_DIR, 'lang' + localeName + '.js'), echartsFile, 'utf8');
    fs.writeFileSync(path.join(OUT_DIR, 'lang' + localeName + '-obj.js'), objFile, 'utf8');

    console.log('Generated locale ' + localeName);
}

function main() {
    if (!fs.existsSync(OUT_DIR)) {
        fs.mkdirSync(OUT_DIR, { recursive: true });
    }
    fs.readdirSync(SRC_DIR)
        .filter(fileName => /^lang.*\.ts$/.test(fileName))
        .forEach(buildLocale);
}

main();

