import langEN from '@/src/i18n/langEN';
import langPTbr from '@/src/i18n/langPT-br';

type Dict = { [key: string]: unknown };

function collectPaths(obj: Dict, prefix: string, out: string[]): string[] {
    Object.keys(obj).forEach(function (key) {
        const val = (obj as Dict)[key];
        const path = prefix ? prefix + '.' + key : key;
        if (val && typeof val === 'object' && !(val instanceof Array)) {
            collectPaths(val as Dict, path, out);
        }
        else {
            out.push(path);
        }
    });
    return out.sort();
}

function collectStrings(obj: Dict, out: string[]): string[] {
    Object.keys(obj).forEach(function (key) {
        const val = (obj as Dict)[key];
        if (typeof val === 'string') {
            out.push(val);
        }
        else if (val instanceof Array) {
            val.forEach(item => typeof item === 'string' && out.push(item));
        }
        else if (val && typeof val === 'object') {
            collectStrings(val as Dict, out);
        }
    });
    return out;
}

describe('i18n/langPT-br', function () {

    it('should keep exactly the same key set as langEN', function () {
        expect(collectPaths(langPTbr as Dict, '', [])).toEqual(collectPaths(langEN as Dict, '', []));
    });

    it('should keep the placeholder tokens of langEN', function () {
        const tokensOf = (locale: Dict) => {
            const tokens: string[] = [];
            collectStrings(locale, []).forEach(function (str) {
                (str.match(/\{[a-zA-Z]+\}/g) || []).forEach(token => tokens.push(token));
            });
            return tokens.sort();
        };
        expect(tokensOf(langPTbr as Dict)).toEqual(tokensOf(langEN as Dict));
    });

    it('should not leave built-in labels untranslated', function () {
        expect(langPTbr.toolbox.restore.title).toEqual('Restaurar');
        expect(langPTbr.toolbox.magicType.title.tiled).toEqual('Lado a lado');
        expect(langPTbr.toolbox.dataView.title).toEqual('Visualização de dados');
        expect(langPTbr.series.typeNames.gauge).toEqual('Medidor');
        expect(langPTbr.series.typeNames.graph).toEqual('Grafo de relacionamentos');
        expect(langPTbr.series.typeNames.pictorialBar).toEqual('Gráfico de barras pictóricas');
        expect(langPTbr.series.typeNames.themeRiver).toEqual('Gráfico de rio temático');
        expect(langPTbr.legend.selector.inverse).toEqual('Inverso');

        // No english leftovers of langEN in the pt-BR strings.
        const englishOnly = [
            'Restore', 'Tile', 'Relationship graph', 'Gauge',
            'Pictorial bar', 'Theme River Map', 'Data View'
        ];
        const ptStrings = collectStrings(langPTbr as Dict, []);
        englishOnly.forEach(function (str) {
            expect(ptStrings.indexOf(str)).toBe(-1);
        });
    });

    it('should provide well formed weekday names', function () {
        expect(langPTbr.time.dayOfWeek).toEqual([
            'Domingo', 'Segunda-feira', 'Terça-feira', 'Quarta-feira',
            'Quinta-feira', 'Sexta-feira', 'Sábado'
        ]);
    });
});

