    const lock = readJSON('package-lock.json');

    it('should pin ws to 7.5.10 in package.json', function () {
        expect(pkg.devDependencies.ws).toEqual('7.5.10');
        // Must stay a dev only dependency, runtime deps are untouched.
        expect(pkg.dependencies.ws).toBeUndefined();
    });

    it('should resolve ws to 7.5.10 in the lock file', function () {
        const entry = lock.packages['node_modules/ws'];
        expect(entry.version).toEqual('7.5.10');
        expect(entry.resolved).toEqual('https://registry.npmjs.org/ws/-/ws-7.5.10.tgz');
        expect(entry.dev).toBe(true);
        // lockfileVersion 2 keeps a legacy `dependencies` mirror.
        expect(lock.dependencies.ws.version).toEqual('7.5.10');
        expect(lock.packages[''].devDependencies.ws).toEqual('7.5.10');
    });

    it('should not leave any ws 7.5.7 reference behind', function () {
        const lockText = fs.readFileSync(path.join(ROOT, 'package-lock.json'), 'utf8');
