const { TypeScriptVersion } = require('@definitelytyped/typescript-versions');
const {
    cleanTypeScriptInstalls,
    installAllTypeScriptVersions,
    installTypeScriptNext,
    typeScriptPath
} = require('@definitelytyped/utils');
const globby = require('globby');
const semver = require('semver');

/**
 * Oldest TypeScript version the ECharts typings are verified against.
 * Everything from this version up to the newest compiler known by
 * `@definitelytyped/typescript-versions` is installed and tested.
 */
const MIN_VERSION = '3.5.0';

/**
 * All TypeScript versions (>= `MIN_VERSION`) that the dts test runs against.
 * `shipped` only lists the already released compilers, `supported` also
 * contains the newer ones, so both lists are merged to make sure regressions
 * on recent TypeScript versions are caught as well.
 *
 * @return {string[]} Sorted list of versions like `['3.5', '3.6', ...]`.
 */
function getTestVersions() {
    const versions = [].concat(TypeScriptVersion.shipped, TypeScriptVersion.supported);
    const tested = [];
    versions.forEach(function (version) {
        if (!semver.lt(version + '.0', MIN_VERSION) && tested.indexOf(version) < 0) {
            tested.push(version);
        }
    });
    return tested.sort((va, vb) => semver.compare(va + '.0', vb + '.0'));
}

async function installTs() {
    // await cleanTypeScriptInstalls();
    // Installs every version known by @definitelytyped/typescript-versions,
    // which covers the whole `getTestVersions()` range (>= 3.5).
    await installAllTypeScriptVersions();
    // Also make the newest compiler available so that the upper bound of the
    // tested range follows the TypeScript releases.
    await installTypeScriptNext();
}

async function runTests() {
    // Lazily required: only needed when the compile tests actually run.
    const { runTsCompile } = require('./pre-publish');
    const compilerOptions = {
        declaration: false,
        importHelpers: false,
        sourceMap: false,
        pretty: false,
        removeComments: false,
        allowJs: false,
        outDir: __dirname + '/../test/types/tmp',
        typeRoots: [__dirname + '/../types/dist'],
        rootDir: __dirname + '/../test/types',

        // Must pass in most strict cases
        strict: true
    };
    const testsList = await globby(__dirname + '/../test/types/*.ts');

    for (let version of getTestVersions()) {
        console.log(`Testing ts version ${version}`);
        const ts = require(typeScriptPath(version));
        await runTsCompile(ts, compilerOptions, testsList);

        console.log(`Finished test of ts version ${version}`);
    }
}

async function main(opts) {
    opts = opts || {};
    if (opts.install !== false) {
        await installTs();
    }
    if (opts.test !== false) {
        await runTests();
    }
}

module.exports = main;
module.exports.MIN_VERSION = MIN_VERSION;
module.exports.getTestVersions = getTestVersions;

const argv = process.argv.slice(2);
main({
    install: argv.indexOf('--no-install') < 0,
    test: argv.indexOf('--install-only') < 0
});

