import * as path from 'path';

const ROOT = path.resolve(__dirname, '../../../..');

const pkg = JSON.parse(fs.readFileSync(path.join(ROOT, 'package.json'), 'utf8'));
const testDtsSource = fs.readFileSync(path.join(ROOT, 'build/testDts.js'), 'utf8');

describe('package/dts compatibility runner', function () {

    it('should expose the dts test through package.json scripts', function () {
        expect(pkg.scripts['test:dts']).toEqual('node build/testDts.js');
        // Installing the compilers can be done on its own (CI cache step).
        expect(pkg.scripts['test:dts:install']).toEqual('node build/testDts.js --install-only');
        expect(pkg.devDependencies['@definitelytyped/typescript-versions']).toBeTruthy();
        expect(pkg.devDependencies['@definitelytyped/utils']).toBeTruthy();
    });

    it('should test every TypeScript version starting at 3.5', function () {
        expect(testDtsSource).toContain('const MIN_VERSION = \'3.5.0\';');
        expect(testDtsSource).toContain('semver.lt(version + \'.0\', MIN_VERSION)');
        expect(testDtsSource).toContain('function getTestVersions()');
        // The tested range must not be limited to the already shipped set.
        expect(testDtsSource).toContain('TypeScriptVersion.supported');
        expect(testDtsSource).toContain('for (let version of getTestVersions())');
    });

    it('should install the whole tested range including the newest compiler', function () {
        expect(testDtsSource).toContain('installAllTypeScriptVersions');
        expect(testDtsSource).toContain('installTypeScriptNext');
    });

    it('should select only versions >= 3.5 and include the newer ones', function () {
        // Re-implements the runner selection over the real version list so the
        // range boundary is checked, not just the source text.
        // eslint-disable-next-line @typescript-eslint/no-var-requires
        const { TypeScriptVersion } = require('@definitelytyped/typescript-versions');
        const all: string[] = [].concat(TypeScriptVersion.shipped, TypeScriptVersion.supported);
        const tested: string[] = [];
        all.forEach(function (version) {
            const num = parseFloat(version);
            if (num >= 3.5 && tested.indexOf(version) < 0) {
                tested.push(version);
            }
        });
        expect(tested.length).toBeGreaterThan(0);
        expect(tested.indexOf('3.4')).toBe(-1);
        expect(tested.indexOf('3.5')).toBeGreaterThanOrEqual(0);
        // Newer than the `shipped` upper bound must be covered too.
        const maxShipped = Math.max.apply(null, TypeScriptVersion.shipped.map(parseFloat));
        const maxTested = Math.max.apply(null, tested.map(parseFloat));
        expect(maxTested).toBeGreaterThanOrEqual(maxShipped);
    });
});

