import * as fs from 'fs';
import * as path from 'path';
import { version, dependencies } from '@/src/core/echarts';
import langEN from '@/src/i18n/langEN';
import langFA from '@/src/i18n/langFA';
import langSV from '@/src/i18n/langSV';

const ROOT = path.resolve(__dirname, '../../../..');
const pkg = JSON.parse(fs.readFileSync(path.join(ROOT, 'package.json'), 'utf8'));

type Dict = { [key: string]: unknown };

function collectPaths(obj: Dict, prefix: string, out: string[]): string[] {
    Object.keys(obj).forEach(function (key) {
        const val = (obj as Dict)[key];
        const keyPath = prefix ? prefix + '.' + key : key;
        if (val && typeof val === 'object' && !(val instanceof Array)) {
            collectPaths(val as Dict, keyPath, out);
        }
        else {
            out.push(keyPath);
        }
    });
    return out.sort();
}

describe('release/v5.6.0', function () {

    it('should report 5.6.0 both in the source and in package.json', function () {
        expect(version).toEqual('5.6.0');
        expect(pkg.version).toEqual('5.6.0');
    });

    it('should depend on zrender 5.6.1 consistently', function () {
        expect(dependencies.zrender).toEqual('5.6.1');
        expect(pkg.dependencies.zrender).toEqual('5.6.1');
    });

    it('should add the FA and SV locales with the langEN key set', function () {
        const enPaths = collectPaths(langEN as Dict, '', []);
        expect(collectPaths(langFA as Dict, '', [])).toEqual(enPaths);
        expect(collectPaths(langSV as Dict, '', [])).toEqual(enPaths);
    });

    it('should ship the generated FA and SV bundles', function () {
        const cases: [string, string][] = [
            ['i18n/langFA.js', 'FA'],
            ['i18n/langSV.js', 'SV']
        ];
        cases.forEach(function ([relPath, localeName]) {
            const content = fs.readFileSync(path.join(ROOT, relPath), 'utf8');
            expect(content).toContain('AUTO-GENERATED FILE. DO NOT MODIFY.');
            expect(content).toContain('var localeObj = {');
            expect(content).toContain('echarts.registerLocale(\'' + localeName + '\', localeObj);');
        });

        ['i18n/langFA-obj.js', 'i18n/langSV-obj.js'].forEach(function (relPath) {
            const content = fs.readFileSync(path.join(ROOT, relPath), 'utf8');
            expect(content).toContain('exports[key] = localeObj[key];');
            expect(content).not.toContain('registerLocale');
        });
    });
});
